import { useState, useEffect } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Box,
  Typography,
  Alert,
} from '@mui/material';
import { DateTimePicker } from '@mui/x-date-pickers/DateTimePicker';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { AdapterDateFns } from '@mui/x-date-pickers/AdapterDateFns';
import { de } from 'date-fns/locale/de';
import { Project } from '../types';

interface InsertEntryDialogProps {
  open: boolean;
  projects: Project[];
  suggestedStartTime?: Date;
  suggestedEndTime?: Date;
  onClose: () => void;
  onInsert: (projectId: string, startTime: Date, endTime: Date) => void;
}

export function InsertEntryDialog({
  open,
  projects,
  suggestedStartTime,
  suggestedEndTime,
  onClose,
  onInsert,
}: InsertEntryDialogProps) {
  const [projectId, setProjectId] = useState('');
  const [startTime, setStartTime] = useState<Date | null>(null);
  const [endTime, setEndTime] = useState<Date | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (open) {
      setStartTime(suggestedStartTime || new Date());
      setEndTime(suggestedEndTime || new Date());
      setProjectId(projects.find(p => p.id === 'break')?.id || projects[0]?.id || '');
      setError(null);
    }
  }, [open, suggestedStartTime, suggestedEndTime, projects]);

  const [submitting,setSubmitting] = useState(false);
  const handleInsert = async () => {
    if(submitting)return;
    setSubmitting(true);
    try {
    if (!projectId || !startTime || !endTime) {
      setError('Please fill in all fields');
      return;
    }

    if (startTime >= endTime) {
      setError('End time must be after start time');
      return;
    }

    await onInsert(projectId, startTime, endTime);
    onClose();
    } catch { /* Keep the draft; repository status displays the failure. */ } finally {setSubmitting(false);}
  };

  const duration = startTime && endTime
    ? Math.max(0, endTime.getTime() - startTime.getTime())
    : 0;

  const formatDuration = (ms: number) => {
    const hours = Math.floor(ms / (1000 * 60 * 60));
    const minutes = Math.floor((ms % (1000 * 60 * 60)) / (1000 * 60));
    if (hours > 0) {
      return `${hours}h ${minutes}m`;
    }
    return `${minutes}m`;
  };

  return (
    <LocalizationProvider dateAdapter={AdapterDateFns} adapterLocale={de}>
      <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
        <DialogTitle>Insert Time Entry</DialogTitle>
        <DialogContent>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            Insert a new time entry. Adjacent entries will be automatically adjusted.
          </Typography>

          {error && (
            <Alert severity="error" sx={{ mb: 2 }}>
              {error}
            </Alert>
          )}

          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 1 }}>
            <FormControl fullWidth>
              <InputLabel>Project</InputLabel>
              <Select
                value={projectId}
                label="Project"
                onChange={(e) => setProjectId(e.target.value)}
              >
                {projects.map((project) => (
                  <MenuItem key={project.id} value={project.id}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                      <span>{project.icon}</span>
                      <span>{project.name}</span>
                    </Box>
                  </MenuItem>
                ))}
              </Select>
            </FormControl>

            <DateTimePicker
              label="Start Time"
              value={startTime}
              onChange={(newValue) => {
                setStartTime(newValue);
                setError(null);
              }}
              slotProps={{ textField: { fullWidth: true } }}
            />

            <DateTimePicker
              label="End Time"
              value={endTime}
              onChange={(newValue) => {
                setEndTime(newValue);
                setError(null);
              }}
              slotProps={{ textField: { fullWidth: true } }}
            />

            {duration > 0 && (
              <Typography variant="body2" sx={{ textAlign: 'center', fontWeight: 'bold' }}>
                Duration: {formatDuration(duration)}
              </Typography>
            )}
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={onClose}>Cancel</Button>
          <Button disabled={submitting} onClick={handleInsert} variant="contained">
            Insert Entry
          </Button>
        </DialogActions>
      </Dialog>
    </LocalizationProvider>
  );
}
