import { useState, useMemo, useEffect } from 'react';
import {
  List,
  ListItem,
  ListItemText,
  ListItemSecondaryAction,
  IconButton,
  Typography,
  Box,
  Chip,
  TextField,
  Button,
  FormControlLabel,
  Checkbox,
  Tabs,
  Tab,
  Tooltip,
  Fab,
  Alert,
  ToggleButtonGroup,
  ToggleButton,
  useMediaQuery,
  useTheme,
  keyframes,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
} from '@mui/material';
import {
  Edit as EditIcon,
  Delete as DeleteIcon,
  Save as SaveIcon,
  Cancel as CancelIcon,
  CallSplit as SplitIcon,
  Add as AddIcon,
  ViewDay as ViewDayIcon,
  ViewWeek as ViewWeekIcon,
  LocalCafe as LocalCafeIcon,
} from '@mui/icons-material';
import { DateTimePicker } from '@mui/x-date-pickers/DateTimePicker';
import { TimePicker } from '@mui/x-date-pickers/TimePicker';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { AdapterDateFns } from '@mui/x-date-pickers/AdapterDateFns';
import { de } from 'date-fns/locale/de';
import { TimeEntry, Project } from '../types';
import { formatDuration, formatTime, formatDate } from '../utils/timeUtils';
import { DayTimeline } from './DayTimeline';
import { WeekTimeline } from './WeekTimeline';
import { InsertEntryDialog } from './InsertEntryDialog';

const pulseAnimation = keyframes`
  0% { opacity: 1; }
  50% { opacity: 0.4; }
  100% { opacity: 1; }
`;

const RUNNING_ENTRY_ID = '__running__';

interface HistoryPanelProps {
  onUpdateEntries?: (changes: {id:string;updates:Partial<TimeEntry>}[]) => Promise<void>;
  timeEntries: TimeEntry[];
  projects: Project[];
  onUpdateEntry: (entryId: string, updates: Partial<TimeEntry>) => void;
  onDeleteEntry: (entryId: string) => void;
  onInsertEntry?: (projectId: string, startTime: Date, endTime: Date) => void;
  onSplitEntry?: (entryId: string, splitTime: Date) => void;
  activeProjectId?: string | null;
  currentSessionStart?: Date | null;
  onUpdateSessionStart?: (newStart: Date) => void;
}

interface EditingEntry {
  saveSessionStart?: (at:Date) => void;
  version?: number;
  previous?: TimeEntry | null;
  next?: TimeEntry | null;
  id: string;
  projectId: string;
  startTime: Date;
  endTime: Date | null;
  description: string;
  adjustPrevious: boolean;
  adjustNext: boolean;
}

interface BreakDialogState {
  entry: TimeEntry;
  breakStart: Date;
  durationMinutes: number;
}

interface SplitDialogState {
  entryId: string;
  originalEntry: TimeEntry;
  splitTime: Date;
}

export const HistoryPanel: React.FC<HistoryPanelProps> = ({
  timeEntries,
  projects,
  onUpdateEntry,
  onUpdateEntries,
  onDeleteEntry,
  onInsertEntry,
  onSplitEntry,
  activeProjectId,
  currentSessionStart,
  onUpdateSessionStart,
}) => {
  const theme = useTheme();
  const isDesktop = useMediaQuery(theme.breakpoints.up('md'));
  const [editingEntry, setEditingEntry] = useState<EditingEntry | null>(null);
  const [tabValue, setTabValue] = useState(0);
  const [timelineMode, setTimelineMode] = useState<'day' | 'week'>('day');
  const [selectedDate, setSelectedDate] = useState(new Date());

  // Default to week view on desktop
  useEffect(() => {
    setTimelineMode(isDesktop ? 'week' : 'day');
  }, [isDesktop]);
  const [insertDialogOpen, setInsertDialogOpen] = useState(false);
  const [insertSuggestion, setInsertSuggestion] = useState<{ start?: Date; end?: Date }>({});
  const [splitDialog, setSplitDialog] = useState<SplitDialogState | null>(null);
  const [breakDialog, setBreakDialog] = useState<BreakDialogState | null>(null);
  const [now, setNow] = useState(new Date());

  // Update `now` every second for live-updating running entry duration
  useEffect(() => {
    if (!activeProjectId || !currentSessionStart) return;
    const interval = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(interval);
  }, [activeProjectId, currentSessionStart]);

  const sortedEntries = useMemo(() => {
    const completed = [...timeEntries]
      .filter(entry => entry.endTime)
      .sort((a, b) => new Date(b.startTime).getTime() - new Date(a.startTime).getTime());

    // Prepend synthetic running entry if tracking is active
    if (activeProjectId && currentSessionStart) {
      const runningEntry: TimeEntry = {
        id: RUNNING_ENTRY_ID,
        projectId: activeProjectId,
        startTime: currentSessionStart,
        endTime: undefined,
        duration: now.getTime() - currentSessionStart.getTime(),
      };
      return [runningEntry, ...completed];
    }

    return completed;
  }, [timeEntries, activeProjectId, currentSessionStart, now]);

  const getProjectName = (projectId: string) => {
    const project = projects.find(p => p.id === projectId);
    return project ? project.name : projectId;
  };

  const getProjectColor = (projectId: string) => {
    const project = projects.find(p => p.id === projectId);
    return project ? project.color : '#808080';
  };

  const CONTIGUITY_THRESHOLD = 60000; // 60 seconds

  // Find adjacent entries for linked editing
  const findAdjacentEntries = (entry: TimeEntry) => {
    const sorted = [...timeEntries]
      .filter(e => e.endTime)
      .sort((a, b) => new Date(a.startTime).getTime() - new Date(b.startTime).getTime());

    const index = sorted.findIndex(e => e.id === entry.id);
    const previous = index > 0 ? sorted[index - 1] : null;
    const next = index < sorted.length - 1 ? sorted[index + 1] : null;

    const isPreviousContiguous = previous?.endTime
      ? Math.abs(new Date(entry.startTime).getTime() - new Date(previous.endTime).getTime()) < CONTIGUITY_THRESHOLD
      : false;
    const isNextContiguous = next
      ? Math.abs(new Date(next.startTime).getTime() - new Date(entry.endTime!).getTime()) < CONTIGUITY_THRESHOLD
      : false;

    return { previous, next, isPreviousContiguous, isNextContiguous };
  };

  const [editValidationError, setEditValidationError] = useState<string | null>(null);

  const handleEdit = (entry: TimeEntry) => {
    const { previous, next, isPreviousContiguous, isNextContiguous } = findAdjacentEntries(entry);
    setEditValidationError(null);
    setEditingEntry({
      id: entry.id,
      version: entry.version,
      previous, next,
      projectId: entry.projectId,
      startTime: new Date(entry.startTime),
      endTime: entry.endTime ? new Date(entry.endTime) : null,
      description: entry.description || '',
      adjustPrevious: isPreviousContiguous,
      adjustNext: isNextContiguous,
    });
  };

  const handleSave = async () => {
    try {
    if (!editingEntry || !editingEntry.endTime) return;

    const entry = timeEntries.find(e => e.id === editingEntry.id);
    if (!entry) return;

    const { previous, next } = editingEntry;

    // Validation: check for negative durations
    const duration = editingEntry.endTime.getTime() - editingEntry.startTime.getTime();
    if (duration <= 0) {
      setEditValidationError('Entry duration must be positive (end time must be after start time).');
      return;
    }

    if (editingEntry.adjustPrevious && previous) {
      const newPrevDuration = editingEntry.startTime.getTime() - new Date(previous.startTime).getTime();
      if (newPrevDuration <= 0) {
        setEditValidationError(`Adjusting the previous entry ("${getProjectName(previous.projectId)}") would result in a negative duration.`);
        return;
      }
    }

    if (editingEntry.adjustNext && next) {
      const newNextDuration = new Date(next.endTime!).getTime() - editingEntry.endTime.getTime();
      if (newNextDuration <= 0) {
        setEditValidationError(`Adjusting the next entry ("${getProjectName(next.projectId)}") would result in a negative duration.`);
        return;
      }
    }

    setEditValidationError(null);

    const changes: {id:string;updates:Partial<TimeEntry>}[] = [];
    // Update the main entry
    changes.push({id:editingEntry.id, updates:{
      version: editingEntry.version,
      projectId: editingEntry.projectId,
      startTime: editingEntry.startTime,
      endTime: editingEntry.endTime,
      duration,
      description: editingEntry.description,
    }});

    // Adjust previous entry if requested
    if (editingEntry.adjustPrevious && previous) {
      const originalStart = new Date(entry.startTime);
      const newStart = editingEntry.startTime;
      if (originalStart.getTime() !== newStart.getTime()) {
        const newPrevEnd = newStart;
        const newPrevDuration = newPrevEnd.getTime() - new Date(previous.startTime).getTime();
        changes.push({id:previous.id, updates:{
          version: previous.version,
          endTime: newPrevEnd,
          duration: newPrevDuration,
        }});
      }
    }

    // Adjust next entry if requested
    if (editingEntry.adjustNext && next) {
      const originalEnd = new Date(entry.endTime!);
      const newEnd = editingEntry.endTime;
      if (originalEnd.getTime() !== newEnd.getTime()) {
        const newNextStart = newEnd;
        const newNextDuration = new Date(next.endTime!).getTime() - newNextStart.getTime();
        changes.push({id:next.id, updates:{
          version: next.version,
          startTime: newNextStart,
          duration: newNextDuration,
        }});
      }
    }

    if (onUpdateEntries) await onUpdateEntries(changes);
    else for (const change of changes) await onUpdateEntry(change.id, change.updates);
    setEditingEntry(null);
    } catch { /* Keep the draft; repository status displays the failure. */ }
  };

  const handleCancel = () => {
    setEditingEntry(null);
  };

  const handleDelete = (entryId: string) => {
    onDeleteEntry(entryId);
    if (editingEntry?.id === entryId) {
      setEditingEntry(null);
    }
  };

  const handleSplitEntry = (entryId: string, splitTime: Date) => {
    const entry = timeEntries.find(e => e.id === entryId);
    if (!entry) return;

    setSplitDialog({
      entryId,
      originalEntry: entry,
      splitTime,
    });
  };

  const confirmSplit = async () => {
    try {
    if (!splitDialog || !onSplitEntry) return;
    await onSplitEntry(splitDialog.entryId, splitDialog.splitTime);
    setSplitDialog(null);
    } catch { /* Keep the draft; repository status displays the failure. */ }
  };

  const breakValidationError = useMemo(() => {
    if (!breakDialog) return null;
    const { entry, breakStart, durationMinutes } = breakDialog;
    if (!entry.endTime) return null;
    const entryStart = new Date(entry.startTime).getTime();
    const entryEnd = new Date(entry.endTime).getTime();
    const bStart = breakStart.getTime();
    const bEnd = bStart + durationMinutes * 60 * 1000;
    if (bStart < entryStart) {
      return 'Break start must be within the entry.';
    }
    if (bEnd > entryEnd) {
      return 'Break extends past the end of the entry.';
    }
    return null;
  }, [breakDialog]);

  const confirmBreak = async () => {
    try {
    if (!breakDialog || !onInsertEntry || breakValidationError) return;
    const breakEnd = new Date(breakDialog.breakStart.getTime() + breakDialog.durationMinutes * 60 * 1000);
    await onInsertEntry('break', breakDialog.breakStart, breakEnd);
    setBreakDialog(null);
    setEditingEntry(null);
    } catch { /* Keep the draft; repository status displays the failure. */ }
  };

  const handleInsertFromTimeline = (startTime: Date, endTime: Date) => {
    setInsertSuggestion({ start: startTime, end: endTime });
    setInsertDialogOpen(true);
  };

  const handleInsertEntry = async (projectId: string, startTime: Date, endTime: Date) => {
    try {
    if (onInsertEntry) {
      await onInsertEntry(projectId, startTime, endTime);
    }
    setInsertDialogOpen(false);
    setInsertSuggestion({});
    } catch { /* Keep the draft; repository status displays the failure. */ }
  };

  const handleTimelineEditEntry = (entry: TimeEntry) => {
    setTabValue(0); // Switch to list view
    handleEdit(entry);
    // Scroll to entry (could be improved)
  };

  return (
    <LocalizationProvider dateAdapter={AdapterDateFns} adapterLocale={de}>
      <Box sx={{ p: 2, pb: 10 }}>
        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 2 }}>
          <Typography variant="h5">
            Time Entries
          </Typography>
          {onInsertEntry && (
            <Tooltip title="Insert new entry">
              <Fab
                size="small"
                color="primary"
                onClick={() => setInsertDialogOpen(true)}
                aria-label="Insert new time entry"
              >
                <AddIcon />
              </Fab>
            </Tooltip>
          )}
        </Box>

        <Tabs
          value={tabValue}
          onChange={(_, newValue) => setTabValue(newValue)}
          sx={{ mb: 2 }}
        >
          <Tab label="List View" />
          <Tab label="Timeline View" />
        </Tabs>

        {tabValue === 0 ? (
          // List View
          sortedEntries.length === 0 ? (
            <Typography variant="body2" color="text.secondary" sx={{ textAlign: 'center', py: 4 }}>
              No time entries yet
            </Typography>
          ) : (
            <List>
              {sortedEntries.map((entry) => {
                const isRunning = entry.id === RUNNING_ENTRY_ID;
                const { previous, next, isPreviousContiguous, isNextContiguous } = isRunning
                  ? { previous: null, next: null, isPreviousContiguous: false, isNextContiguous: false }
                  : findAdjacentEntries(entry);

                return (
                  <ListItem key={entry.id} divider>
                    {isRunning && editingEntry?.id === RUNNING_ENTRY_ID ? (
                      // Editing running entry start time
                      <Box sx={{ width: '100%' }}>
                        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                          <DateTimePicker
                            label="Start Time"
                            value={editingEntry.startTime}
                            onChange={(newValue) => {
                              if (newValue) {
                                setEditingEntry(prev => prev ? { ...prev, startTime: newValue } : null);
                              }
                            }}
                            slotProps={{ textField: { size: 'small', fullWidth: true } }}
                          />
                          <TextField
                            label="Description"
                            value={editingEntry.description}
                            onChange={(e) => {
                              setEditingEntry(prev => prev ? { ...prev, description: e.target.value } : null);
                            }}
                            size="small"
                            fullWidth
                          />
                          <Box sx={{ display: 'flex', gap: 1 }}>
                            <Button
                              startIcon={<SaveIcon />}
                              onClick={async () => {
                                if (editingEntry?.saveSessionStart) {
                                  try { await editingEntry.saveSessionStart(editingEntry.startTime); } catch { return; }
                                }
                                setEditingEntry(null);
                              }}
                              variant="contained"
                              size="small"
                            >
                              Save
                            </Button>
                            <Button
                              startIcon={<CancelIcon />}
                              onClick={handleCancel}
                              variant="outlined"
                              size="small"
                            >
                              Cancel
                            </Button>
                          </Box>
                        </Box>
                      </Box>
                    ) : isRunning ? (
                      // Display running entry
                      <>
                        <ListItemText
                          primary={
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                              <Chip
                                label={getProjectName(entry.projectId)}
                                size="small"
                                sx={{ backgroundColor: getProjectColor(entry.projectId), color: 'white' }}
                              />
                              <Chip
                                label="Running"
                                size="small"
                                color="success"
                                sx={{
                                  animation: `${pulseAnimation} 2s ease-in-out infinite`,
                                  fontWeight: 'bold',
                                }}
                              />
                              <Typography variant="body2" color="text.secondary">
                                {formatDate(new Date(entry.startTime))}
                              </Typography>
                            </Box>
                          }
                          secondary={
                            <Box>
                              <Typography variant="body2">
                                {formatTime(new Date(entry.startTime))} - ...
                              </Typography>
                              <Typography variant="body2" sx={{ fontWeight: 'bold', color: 'success.main' }}>
                                Duration: {formatDuration(now.getTime() - new Date(entry.startTime).getTime())}
                              </Typography>
                            </Box>
                          }
                        />
                        <ListItemSecondaryAction>
                          <IconButton
                            edge="end"
                            aria-label="Edit running entry"
                            onClick={() => {
                              setEditingEntry({
                                id: RUNNING_ENTRY_ID,
                                saveSessionStart: onUpdateSessionStart,
                                projectId: entry.projectId,
                                startTime: new Date(entry.startTime),
                                endTime: null,
                                description: '',
                                adjustPrevious: false,
                                adjustNext: false,
                              });
                            }}
                            sx={{ mr: 1 }}
                          >
                            <EditIcon />
                          </IconButton>
                        </ListItemSecondaryAction>
                      </>
                    ) : editingEntry?.id === entry.id ? (
                      <Box sx={{ width: '100%' }}>
                        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                          <FormControl fullWidth size="small">
                            <InputLabel>Project</InputLabel>
                            <Select
                              value={editingEntry.projectId}
                              label="Project"
                              onChange={(e) => setEditingEntry(prev =>
                                prev ? { ...prev, projectId: e.target.value } : null
                              )}
                            >
                              {projects.map((project) => (
                                <MenuItem key={project.id} value={project.id}>
                                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                    <span>{project.icon}</span>
                                    <span>{project.name}</span>
                                  </Box>
                                </MenuItem>
                              ))}
                            </Select>
                          </FormControl>
                          <Box sx={{ display: 'flex', gap: 2, flexDirection: { xs: 'column', sm: 'row' } }}>
                            <Box sx={{ flex: 1 }}>
                              <DateTimePicker
                                label="Start Time"
                                value={editingEntry.startTime}
                                onChange={(newValue) => {
                                  if (newValue) {
                                    setEditingEntry(prev => prev ? { ...prev, startTime: newValue } : null);
                                  }
                                }}
                                slotProps={{ textField: { size: 'small', fullWidth: true } }}
                              />
                              {previous && (
                                <FormControlLabel
                                  control={
                                    <Checkbox
                                      size="small"
                                      checked={editingEntry.adjustPrevious}
                                      onChange={(e) => setEditingEntry(prev =>
                                        prev ? { ...prev, adjustPrevious: e.target.checked } : null
                                      )}
                                    />
                                  }
                                  label={
                                    <Typography variant="caption">
                                      Adjust previous ({getProjectName(previous.projectId)}){isPreviousContiguous ? ' (contiguous)' : ''}
                                    </Typography>
                                  }
                                />
                              )}
                            </Box>
                            <Box sx={{ flex: 1 }}>
                              <DateTimePicker
                                label="End Time"
                                value={editingEntry.endTime}
                                onChange={(newValue) => {
                                  if (newValue) {
                                    setEditingEntry(prev => prev ? { ...prev, endTime: newValue } : null);
                                  }
                                }}
                                slotProps={{ textField: { size: 'small', fullWidth: true } }}
                              />
                              {next && (
                                <FormControlLabel
                                  control={
                                    <Checkbox
                                      size="small"
                                      checked={editingEntry.adjustNext}
                                      onChange={(e) => setEditingEntry(prev =>
                                        prev ? { ...prev, adjustNext: e.target.checked } : null
                                      )}
                                    />
                                  }
                                  label={
                                    <Typography variant="caption">
                                      Adjust next ({getProjectName(next.projectId)}){isNextContiguous ? ' (contiguous)' : ''}
                                    </Typography>
                                  }
                                />
                              )}
                            </Box>
                          </Box>
                          <TextField
                            label="Description"
                            value={editingEntry.description}
                            onChange={(e) => {
                              setEditingEntry(prev => prev ? { ...prev, description: e.target.value } : null);
                            }}
                            size="small"
                            fullWidth
                          />
                          {editingEntry.startTime && editingEntry.endTime && (
                            <Typography variant="body2" color="text.secondary">
                              Duration: {formatDuration(editingEntry.endTime.getTime() - editingEntry.startTime.getTime())}
                            </Typography>
                          )}
                          {editValidationError && (
                            <Alert severity="error" onClose={() => setEditValidationError(null)} sx={{ mb: 1 }}>
                              {editValidationError}
                            </Alert>
                          )}
                          <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                            <Button
                              startIcon={<SaveIcon />}
                              onClick={handleSave}
                              variant="contained"
                              size="small"
                            >
                              Save
                            </Button>
                            <Button
                              startIcon={<CancelIcon />}
                              onClick={handleCancel}
                              variant="outlined"
                              size="small"
                            >
                              Cancel
                            </Button>
                            {onInsertEntry && entry.endTime && entry.duration >= 5 * 60 * 1000 && (
                              <Button
                                startIcon={<LocalCafeIcon />}
                                onClick={() => {
                                  const start = new Date(entry.startTime).getTime();
                                  const end = new Date(entry.endTime!).getTime();
                                  setBreakDialog({
                                    entry,
                                    breakStart: new Date((start + end) / 2),
                                    durationMinutes: 30,
                                  });
                                }}
                                variant="outlined"
                                size="small"
                              >
                                Add Break
                              </Button>
                            )}
                            <Button
                              startIcon={<DeleteIcon />}
                              onClick={() => handleDelete(entry.id)}
                              color="error"
                              size="small"
                              sx={{ ml: 'auto' }}
                            >
                              Delete
                            </Button>
                          </Box>
                        </Box>
                      </Box>
                    ) : (
                      <>
                        <ListItemText
                          primary={
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                              <Chip
                                label={getProjectName(entry.projectId)}
                                size="small"
                                sx={{ backgroundColor: getProjectColor(entry.projectId), color: 'white' }}
                              />
                              <Typography variant="body2" color="text.secondary">
                                {formatDate(new Date(entry.startTime))}
                              </Typography>
                            </Box>
                          }
                          secondary={
                            <Box>
                              <Typography variant="body2">
                                {formatTime(new Date(entry.startTime))} - {formatTime(new Date(entry.endTime!))}
                              </Typography>
                              <Typography variant="body2" sx={{ fontWeight: 'bold' }}>
                                Duration: {formatDuration(entry.duration)}
                              </Typography>
                              {entry.description && (
                                <Typography variant="body2" color="text.secondary">
                                  {entry.description}
                                </Typography>
                              )}
                            </Box>
                          }
                        />
                        <ListItemSecondaryAction>
                          {entry.duration >= 30 * 60 * 1000 && onSplitEntry && (
                            <Tooltip title="Split entry">
                              <IconButton
                                edge="end"
                                aria-label="Split entry"
                                onClick={() => {
                                  const start = new Date(entry.startTime).getTime();
                                  const end = new Date(entry.endTime!).getTime();
                                  handleSplitEntry(entry.id, new Date((start + end) / 2));
                                }}
                                sx={{ mr: 1 }}
                              >
                                <SplitIcon />
                              </IconButton>
                            </Tooltip>
                          )}
                          <IconButton edge="end" aria-label="Edit entry" onClick={() => handleEdit(entry)} sx={{ mr: 1 }}>
                            <EditIcon />
                          </IconButton>
                          <IconButton edge="end" aria-label="Delete entry" onClick={() => handleDelete(entry.id)} color="error">
                            <DeleteIcon />
                          </IconButton>
                        </ListItemSecondaryAction>
                      </>
                    )}
                  </ListItem>
                );
              })}
            </List>
          )
        ) : (
          // Timeline View
          <>
            <Box sx={{ display: 'flex', justifyContent: 'flex-end', mb: 1 }}>
              <ToggleButtonGroup
                value={timelineMode}
                exclusive
                onChange={(_, value) => value && setTimelineMode(value)}
                size="small"
              >
                <ToggleButton value="day" aria-label="Day view">
                  <ViewDayIcon fontSize="small" sx={{ mr: 0.5 }} />
                  <Typography variant="caption">Day</Typography>
                </ToggleButton>
                <ToggleButton value="week" aria-label="Week view">
                  <ViewWeekIcon fontSize="small" sx={{ mr: 0.5 }} />
                  <Typography variant="caption">Week</Typography>
                </ToggleButton>
              </ToggleButtonGroup>
            </Box>
            {timelineMode === 'day' ? (
              <DayTimeline
                timeEntries={timeEntries}
                projects={projects}
                selectedDate={selectedDate}
                onDateChange={setSelectedDate}
                onEditEntry={handleTimelineEditEntry}
                onSplitEntry={handleSplitEntry}
                onInsertEntry={handleInsertFromTimeline}
                onDeleteEntry={handleDelete}
                onFillWithBreak={onInsertEntry ? (start, end) => onInsertEntry('break', start, end) : undefined}
                onInsertBreakAtBoundary={onInsertEntry ? (boundaryTime, durationMinutes) => {
                  const breakEnd = new Date(boundaryTime.getTime() + durationMinutes * 60 * 1000);
                  onInsertEntry('break', boundaryTime, breakEnd);
                } : undefined}
                activeProjectId={activeProjectId}
                currentSessionStart={currentSessionStart}
              />
            ) : (
              <WeekTimeline
                timeEntries={timeEntries}
                projects={projects}
                selectedDate={selectedDate}
                onDateChange={setSelectedDate}
                onEditEntry={handleTimelineEditEntry}
                onSelectDay={(date) => {
                  setSelectedDate(date);
                  setTimelineMode('day');
                }}
                activeProjectId={activeProjectId}
                currentSessionStart={currentSessionStart}
              />
            )}
          </>
        )}
      </Box>

      {/* Insert Entry Dialog */}
      <InsertEntryDialog
        open={insertDialogOpen}
        projects={projects}
        suggestedStartTime={insertSuggestion.start}
        suggestedEndTime={insertSuggestion.end}
        onClose={() => {
          setInsertDialogOpen(false);
          setInsertSuggestion({});
        }}
        onInsert={handleInsertEntry}
      />

      {/* Split Entry Dialog */}
      {splitDialog && (
        <LocalizationProvider dateAdapter={AdapterDateFns} adapterLocale={de}>
          <Box
            sx={{
              position: 'fixed',
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              bgcolor: 'rgba(0,0,0,0.5)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              zIndex: 1300,
            }}
            onClick={() => setSplitDialog(null)}
          >
            <Box
              sx={{
                bgcolor: 'background.paper',
                borderRadius: 2,
                p: 3,
                minWidth: 300,
                maxWidth: 400,
              }}
              onClick={(e) => e.stopPropagation()}
            >
              <Typography variant="h6" gutterBottom>
                Split Entry
              </Typography>
              <Typography variant="body2" color="text.secondary" gutterBottom>
                Split "{getProjectName(splitDialog.originalEntry.projectId)}" entry at:
              </Typography>
              <Box sx={{ my: 2 }}>
                <TimePicker
                  label="Split at"
                  value={splitDialog.splitTime}
                  onChange={(newValue) => {
                    if (newValue) {
                      setSplitDialog(prev => prev ? { ...prev, splitTime: newValue } : null);
                    }
                  }}
                  slotProps={{ textField: { fullWidth: true } }}
                />
              </Box>
              <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 2 }}>
                Original: {formatTime(new Date(splitDialog.originalEntry.startTime))} - {formatTime(new Date(splitDialog.originalEntry.endTime!))}
              </Typography>
              <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end' }}>
                <Button onClick={() => setSplitDialog(null)}>Cancel</Button>
                <Button variant="contained" onClick={confirmSplit}>Split</Button>
              </Box>
            </Box>
          </Box>
        </LocalizationProvider>
      )}

      {/* Add Break Within Entry Dialog */}
      {breakDialog && breakDialog.entry.endTime && (() => {
        const entry = breakDialog.entry;
        const entryStart = new Date(entry.startTime);
        const entryEnd = new Date(entry.endTime!);
        const breakStart = breakDialog.breakStart;
        const breakEnd = new Date(breakStart.getTime() + breakDialog.durationMinutes * 60 * 1000);
        return (
          <LocalizationProvider dateAdapter={AdapterDateFns} adapterLocale={de}>
            <Box
              sx={{
                position: 'fixed',
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
                bgcolor: 'rgba(0,0,0,0.5)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                zIndex: 1300,
              }}
              onClick={() => setBreakDialog(null)}
            >
              <Box
                sx={{
                  bgcolor: 'background.paper',
                  borderRadius: 2,
                  p: 3,
                  minWidth: 320,
                  maxWidth: 440,
                  width: '100%',
                  mx: 2,
                }}
                onClick={(e) => e.stopPropagation()}
              >
                <Typography variant="h6" gutterBottom>
                  Add Break Within Entry
                </Typography>
                <Typography variant="body2" color="text.secondary" gutterBottom>
                  Insert a break into "{getProjectName(entry.projectId)}" ({formatTime(entryStart)} – {formatTime(entryEnd)}).
                </Typography>
                <Box sx={{ my: 2 }}>
                  <TimePicker
                    label="Break starts at"
                    value={breakStart}
                    onChange={(newValue) => {
                      if (newValue && breakDialog) {
                        // Combine the picked time-of-day with the entry's date
                        const combined = new Date(entryStart);
                        combined.setHours(newValue.getHours(), newValue.getMinutes(), 0, 0);
                        setBreakDialog({ ...breakDialog, breakStart: combined });
                      }
                    }}
                    slotProps={{ textField: { fullWidth: true, size: 'small' } }}
                  />
                </Box>
                <Typography variant="body2" sx={{ mb: 1 }}>Duration</Typography>
                <ToggleButtonGroup
                  value={breakDialog.durationMinutes}
                  exclusive
                  onChange={(_, value) => {
                    if (value && breakDialog) {
                      setBreakDialog({ ...breakDialog, durationMinutes: value });
                    }
                  }}
                  size="small"
                  sx={{ mb: 2, display: 'flex', flexWrap: 'wrap' }}
                >
                  {[15, 30, 45, 60].map((m) => (
                    <ToggleButton key={m} value={m} sx={{ flex: '1 1 auto' }}>
                      {m} min
                    </ToggleButton>
                  ))}
                </ToggleButtonGroup>
                <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 2 }}>
                  Result: {formatTime(entryStart)}–{formatTime(breakStart)} work · {formatTime(breakStart)}–{formatTime(breakEnd)} break · {formatTime(breakEnd)}–{formatTime(entryEnd)} work
                </Typography>
                {breakValidationError && (
                  <Alert severity="error" sx={{ mb: 2 }}>
                    {breakValidationError}
                  </Alert>
                )}
                <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end' }}>
                  <Button onClick={() => setBreakDialog(null)}>Cancel</Button>
                  <Button
                    variant="contained"
                    onClick={confirmBreak}
                    disabled={!!breakValidationError}
                  >
                    Add Break
                  </Button>
                </Box>
              </Box>
            </Box>
          </LocalizationProvider>
        );
      })()}
    </LocalizationProvider>
  );
};
