import { useState, useMemo, useRef, useEffect } from 'react';
import {
  Box,
  Typography,
  Paper,
  IconButton,
  Tooltip,
  Chip,
  Popover,
  Button,
  keyframes,
} from '@mui/material';
import {
  ChevronLeft as ChevronLeftIcon,
  ChevronRight as ChevronRightIcon,
  Today as TodayIcon,
  CallSplit as SplitIcon,
  AddCircleOutline as InsertIcon,
  FreeBreakfast as BreakIcon,
  Delete as DeleteIcon,
} from '@mui/icons-material';
import { TimeEntry, Project } from '../types';
import { formatTime, formatDuration, formatDate } from '../utils/timeUtils';

const pulseAnimation = keyframes`
  0% { opacity: 0.85; }
  50% { opacity: 0.55; }
  100% { opacity: 0.85; }
`;

interface DayTimelineProps {
  timeEntries: TimeEntry[];
  projects: Project[];
  selectedDate: Date;
  onDateChange: (date: Date) => void;
  onEditEntry: (entry: TimeEntry) => void;
  onSplitEntry: (entryId: string, splitTime: Date) => void;
  onInsertEntry: (startTime: Date, endTime: Date) => void;
  onDeleteEntry?: (entryId: string) => void;
  onFillWithBreak?: (startTime: Date, endTime: Date) => void;
  onInsertBreakAtBoundary?: (boundaryTime: Date, durationMinutes: number) => void;
  activeProjectId?: string | null;
  currentSessionStart?: Date | null;
}

const HOUR_HEIGHT = 60; // pixels per hour
const TIMELINE_START_HOUR = 6; // 6 AM
const TIMELINE_END_HOUR = 22; // 10 PM
const TOTAL_HOURS = TIMELINE_END_HOUR - TIMELINE_START_HOUR;

export function DayTimeline({
  timeEntries,
  projects,
  selectedDate,
  onDateChange,
  onEditEntry,
  onSplitEntry,
  onInsertEntry,
  onDeleteEntry,
  onFillWithBreak,
  onInsertBreakAtBoundary,
  activeProjectId,
  currentSessionStart,
}: DayTimelineProps) {
  const [hoveredGapIndex, setHoveredGapIndex] = useState<number | null>(null);
  const [breakPopover, setBreakPopover] = useState<{ anchorEl: HTMLElement; boundaryTime: Date } | null>(null);
  const timelineRef = useRef<HTMLDivElement>(null);
  const [now, setNow] = useState(new Date());

  // Update `now` every 15 seconds for timeline rendering
  useEffect(() => {
    if (!activeProjectId || !currentSessionStart) return;
    const interval = setInterval(() => setNow(new Date()), 15000);
    return () => clearInterval(interval);
  }, [activeProjectId, currentSessionStart]);

  // Filter entries for selected day (including running entry)
  const dayEntries = useMemo(() => {
    const dayStart = new Date(selectedDate);
    dayStart.setHours(0, 0, 0, 0);
    const dayEnd = new Date(selectedDate);
    dayEnd.setHours(23, 59, 59, 999);

    const completed = timeEntries
      .filter(entry => {
        if (!entry.endTime) return false;
        const entryStart = new Date(entry.startTime);
        return entryStart >= dayStart && entryStart <= dayEnd;
      })
      .sort((a, b) => new Date(a.startTime).getTime() - new Date(b.startTime).getTime());

    // Add running entry if it starts on the selected day
    if (activeProjectId && currentSessionStart) {
      const sessionStart = new Date(currentSessionStart);
      if (sessionStart >= dayStart && sessionStart <= dayEnd) {
        const runningEntry: TimeEntry = {
          id: '__running__',
          projectId: activeProjectId,
          startTime: currentSessionStart,
          endTime: undefined,
          duration: now.getTime() - currentSessionStart.getTime(),
        };
        // Insert in sorted position
        const insertIndex = completed.findIndex(
          e => new Date(e.startTime).getTime() > sessionStart.getTime()
        );
        if (insertIndex === -1) {
          completed.push(runningEntry);
        } else {
          completed.splice(insertIndex, 0, runningEntry);
        }
      }
    }

    return completed;
  }, [timeEntries, selectedDate, activeProjectId, currentSessionStart, now]);

  // Calculate gaps between entries
  const gaps = useMemo(() => {
    const result: { start: Date; end: Date }[] = [];
    for (let i = 0; i < dayEntries.length - 1; i++) {
      const currentEnd = dayEntries[i].endTime ? new Date(dayEntries[i].endTime!) : now;
      const nextStart = new Date(dayEntries[i + 1].startTime);
      const gapMs = nextStart.getTime() - currentEnd.getTime();
      // Only show gaps > 1 minute
      if (gapMs > 60000) {
        result.push({ start: currentEnd, end: nextStart });
      }
    }
    return result;
  }, [dayEntries, now]);

  // Detect boundaries between connected entries (gap <= 1 minute)
  const boundaries = useMemo(() => {
    const result: { time: Date; topEntryId: string; bottomEntryId: string }[] = [];
    for (let i = 0; i < dayEntries.length - 1; i++) {
      if (dayEntries[i].id === '__running__' || dayEntries[i + 1].id === '__running__') continue;
      const currentEnd = dayEntries[i].endTime ? new Date(dayEntries[i].endTime!) : null;
      if (!currentEnd) continue;
      const nextStart = new Date(dayEntries[i + 1].startTime);
      const gapMs = nextStart.getTime() - currentEnd.getTime();
      if (gapMs <= 60000) {
        result.push({ time: currentEnd, topEntryId: dayEntries[i].id, bottomEntryId: dayEntries[i + 1].id });
      }
    }
    return result;
  }, [dayEntries]);

  const getProject = (projectId: string) => {
    return projects.find(p => p.id === projectId);
  };

  const timeToPosition = (date: Date): number => {
    const hours = date.getHours() + date.getMinutes() / 60;
    const adjustedHours = Math.max(0, Math.min(hours - TIMELINE_START_HOUR, TOTAL_HOURS));
    return adjustedHours * HOUR_HEIGHT;
  };

  const getEntryHeight = (entry: TimeEntry): number => {
    const start = new Date(entry.startTime);
    const end = entry.endTime ? new Date(entry.endTime) : now;
    const durationHours = (end.getTime() - start.getTime()) / (1000 * 60 * 60);
    return Math.max(20, durationHours * HOUR_HEIGHT); // Minimum 20px height
  };

  const handlePrevDay = () => {
    const newDate = new Date(selectedDate);
    newDate.setDate(newDate.getDate() - 1);
    onDateChange(newDate);
  };

  const handleNextDay = () => {
    const newDate = new Date(selectedDate);
    newDate.setDate(newDate.getDate() + 1);
    onDateChange(newDate);
  };

  const handleToday = () => {
    onDateChange(new Date());
  };

  const isToday = useMemo(() => {
    const today = new Date();
    return (
      selectedDate.getDate() === today.getDate() &&
      selectedDate.getMonth() === today.getMonth() &&
      selectedDate.getFullYear() === today.getFullYear()
    );
  }, [selectedDate]);

  // Generate hour markers
  const hourMarkers = [];
  for (let hour = TIMELINE_START_HOUR; hour <= TIMELINE_END_HOUR; hour++) {
    hourMarkers.push(hour);
  }

  return (
    <Box sx={{ p: 2 }} role="region" aria-label="Day timeline">
      {/* Date Navigation */}
      <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center', mb: 2, gap: 1 }}>
        <IconButton onClick={handlePrevDay} aria-label="Previous day">
          <ChevronLeftIcon />
        </IconButton>
        <Typography variant="h6" sx={{ minWidth: 200, textAlign: 'center' }}>
          {formatDate(selectedDate)}
          {isToday && (
            <Chip label="Today" size="small" color="primary" sx={{ ml: 1 }} />
          )}
        </Typography>
        <IconButton onClick={handleNextDay} aria-label="Next day">
          <ChevronRightIcon />
        </IconButton>
        {!isToday && (
          <Tooltip title="Go to today">
            <IconButton onClick={handleToday} aria-label="Go to today">
              <TodayIcon />
            </IconButton>
          </Tooltip>
        )}
      </Box>

      {/* Timeline */}
      <Paper sx={{ position: 'relative', overflow: 'hidden' }}>
        <Box
          ref={timelineRef}
          sx={{
            display: 'flex',
            height: TOTAL_HOURS * HOUR_HEIGHT + 40,
            position: 'relative',
          }}
        >
          {/* Hour labels */}
          <Box sx={{ width: 60, flexShrink: 0, borderRight: '1px solid', borderColor: 'divider' }}>
            {hourMarkers.map((hour) => (
              <Box
                key={hour}
                sx={{
                  position: 'absolute',
                  top: (hour - TIMELINE_START_HOUR) * HOUR_HEIGHT + 20,
                  left: 0,
                  width: 55,
                  textAlign: 'right',
                  pr: 1,
                }}
              >
                <Typography variant="caption" color="text.secondary">
                  {hour.toString().padStart(2, '0')}:00
                </Typography>
              </Box>
            ))}
          </Box>

          {/* Timeline content */}
          <Box sx={{ flex: 1, position: 'relative', pt: '20px' }}>
            {/* Hour grid lines */}
            {hourMarkers.map((hour) => (
              <Box
                key={hour}
                sx={{
                  position: 'absolute',
                  top: (hour - TIMELINE_START_HOUR) * HOUR_HEIGHT + 20,
                  left: 0,
                  right: 0,
                  borderTop: '1px solid',
                  borderColor: 'divider',
                  opacity: 0.5,
                }}
              />
            ))}

            {/* Time entries */}
            {dayEntries.map((entry) => {
              const project = getProject(entry.projectId);
              const top = timeToPosition(new Date(entry.startTime)) + 20;
              const height = getEntryHeight(entry);
              const isRunning = entry.id === '__running__';
              const entryEnd = entry.endTime ? new Date(entry.endTime) : now;

              return (
                <Tooltip
                  key={entry.id}
                  title={
                    <Box>
                      <Typography variant="body2">
                        {project?.name || entry.projectId}
                        {isRunning ? ' (Running)' : ''}
                      </Typography>
                      <Typography variant="caption">
                        {formatTime(new Date(entry.startTime))} - {isRunning ? 'now' : formatTime(new Date(entry.endTime!))}
                      </Typography>
                      <br />
                      <Typography variant="caption">
                        Duration: {formatDuration(isRunning ? now.getTime() - new Date(entry.startTime).getTime() : entry.duration)}
                      </Typography>
                    </Box>
                  }
                  placement="right"
                >
                  <Box
                    tabIndex={0}
                    role="button"
                    aria-label={`${project?.name || entry.projectId}: ${formatTime(new Date(entry.startTime))} - ${isRunning ? 'now' : formatTime(entryEnd)}, ${formatDuration(isRunning ? now.getTime() - new Date(entry.startTime).getTime() : entry.duration)}`}
                    onClick={() => !isRunning && onEditEntry(entry)}
                    onKeyDown={(e: React.KeyboardEvent) => {
                      if (!isRunning && (e.key === 'Enter' || e.key === ' ')) {
                        e.preventDefault();
                        onEditEntry(entry);
                      }
                    }}
                    sx={{
                      position: 'absolute',
                      top,
                      left: 8,
                      right: 48,
                      height,
                      backgroundColor: project?.color || '#808080',
                      opacity: 0.85,
                      borderRadius: 1,
                      borderBottom: isRunning ? '3px dashed rgba(255,255,255,0.6)' : 'none',
                      cursor: isRunning ? 'default' : 'pointer',
                      display: 'flex',
                      alignItems: 'center',
                      px: 1,
                      overflow: 'hidden',
                      ...(isRunning ? {
                        animation: `${pulseAnimation} 3s ease-in-out infinite`,
                        backgroundImage: 'repeating-linear-gradient(45deg, transparent, transparent 10px, rgba(255,255,255,0.1) 10px, rgba(255,255,255,0.1) 20px)',
                      } : {}),
                      '&:hover': {
                        opacity: 1,
                        boxShadow: 2,
                      },
                    }}
                  >
                    <Typography
                      variant="caption"
                      sx={{
                        color: 'white',
                        fontWeight: 'bold',
                        textShadow: '1px 1px 2px rgba(0,0,0,0.5)',
                        whiteSpace: 'nowrap',
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                      }}
                    >
                      {project?.icon} {project?.name} {isRunning && '(Running)'}
                    </Typography>
                  </Box>
                </Tooltip>
              );
            })}

            {/* Split buttons on entries */}
            {dayEntries.map((entry) => {
              if (entry.id === '__running__') return null;
              const top = timeToPosition(new Date(entry.startTime)) + 20;
              const height = getEntryHeight(entry);
              // Only show split button if entry is longer than 30 minutes
              if (entry.duration < 30 * 60 * 1000) return null;

              return (
                <Tooltip key={`split-${entry.id}`} title="Split entry">
                  <IconButton
                    size="small"
                    aria-label="Split entry"
                    onClick={(e) => {
                      e.stopPropagation();
                      // Split at the middle of the entry
                      const start = new Date(entry.startTime).getTime();
                      const end = new Date(entry.endTime!).getTime();
                      const middle = new Date((start + end) / 2);
                      onSplitEntry(entry.id, middle);
                    }}
                    sx={{
                      position: 'absolute',
                      top: top + height / 2 - 12,
                      right: 12,
                      backgroundColor: 'background.paper',
                      '&:hover': {
                        backgroundColor: 'action.hover',
                      },
                    }}
                  >
                    <SplitIcon fontSize="small" />
                  </IconButton>
                </Tooltip>
              );
            })}

            {/* Delete buttons on entries */}
            {onDeleteEntry && dayEntries.map((entry) => {
              if (entry.id === '__running__') return null;
              const top = timeToPosition(new Date(entry.startTime)) + 20;
              const height = getEntryHeight(entry);
              const hasSplitButton = entry.duration >= 30 * 60 * 1000;

              return (
                <Tooltip key={`delete-${entry.id}`} title="Delete entry">
                  <IconButton
                    size="small"
                    color="error"
                    aria-label="Delete entry"
                    onClick={(e) => {
                      e.stopPropagation();
                      onDeleteEntry(entry.id);
                    }}
                    sx={{
                      position: 'absolute',
                      top: hasSplitButton ? top + height / 2 + 12 : top + height / 2 - 12,
                      right: 12,
                      backgroundColor: 'background.paper',
                      '&:hover': {
                        backgroundColor: 'error.light',
                        color: 'white',
                      },
                    }}
                  >
                    <DeleteIcon fontSize="small" />
                  </IconButton>
                </Tooltip>
              );
            })}

            {/* Gaps with insert buttons */}
            {gaps.map((gap, index) => {
              const top = timeToPosition(gap.start) + 20;
              const height = Math.max(20, timeToPosition(gap.end) - timeToPosition(gap.start));
              const isHovered = hoveredGapIndex === index;
              const gapMs = gap.end.getTime() - gap.start.getTime();
              const showDuration = gapMs > 5 * 60 * 1000; // > 5 minutes

              return (
                <Box
                  key={`gap-${index}`}
                  onMouseEnter={() => setHoveredGapIndex(index)}
                  onMouseLeave={() => setHoveredGapIndex(null)}
                  sx={{
                    position: 'absolute',
                    top,
                    left: 8,
                    right: 48,
                    height,
                    backgroundColor: isHovered ? 'action.hover' : 'transparent',
                    borderRadius: 1,
                    cursor: 'pointer',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    gap: 0.5,
                    border: isHovered ? '2px dashed' : showDuration ? '1px dashed' : 'none',
                    borderColor: isHovered ? 'primary.main' : 'divider',
                  }}
                >
                  {showDuration && !isHovered && (
                    <Typography variant="caption" color="text.secondary" sx={{ fontSize: '0.65rem' }}>
                      {formatDuration(gapMs)}
                    </Typography>
                  )}
                  {isHovered && (
                    <>
                      <Tooltip title={`Insert entry (${formatDuration(gapMs)} gap)`}>
                        <IconButton size="small" color="primary" aria-label={`Insert entry in ${formatDuration(gapMs)} gap`} onClick={() => onInsertEntry(gap.start, gap.end)}>
                          <InsertIcon />
                        </IconButton>
                      </Tooltip>
                      {onFillWithBreak && (
                        <Tooltip title="Fill with break">
                          <IconButton
                            size="small"
                            color="warning"
                            aria-label="Fill gap with break"
                            onClick={(e) => {
                              e.stopPropagation();
                              onFillWithBreak(gap.start, gap.end);
                            }}
                          >
                            <BreakIcon />
                          </IconButton>
                        </Tooltip>
                      )}
                    </>
                  )}
                </Box>
              );
            })}

            {/* Break insertion buttons at connected boundaries */}
            {onInsertBreakAtBoundary && boundaries.map((boundary, index) => {
              const top = timeToPosition(boundary.time) + 20;
              return (
                <Tooltip key={`boundary-${index}`} title="Insert break between entries">
                  <IconButton
                    size="small"
                    color="warning"
                    aria-label="Insert break between connected entries"
                    onClick={(e) => setBreakPopover({ anchorEl: e.currentTarget, boundaryTime: boundary.time })}
                    sx={{
                      position: 'absolute',
                      top: top - 12,
                      right: 12,
                      backgroundColor: 'background.paper',
                      zIndex: 2,
                      '&:hover': {
                        backgroundColor: 'warning.light',
                        color: 'white',
                      },
                    }}
                  >
                    <BreakIcon fontSize="small" />
                  </IconButton>
                </Tooltip>
              );
            })}

            {/* Current time indicator */}
            {isToday && (
              <Box
                sx={{
                  position: 'absolute',
                  top: timeToPosition(new Date()) + 20,
                  left: 0,
                  right: 0,
                  height: 2,
                  backgroundColor: 'error.main',
                  '&::before': {
                    content: '""',
                    position: 'absolute',
                    left: -4,
                    top: -4,
                    width: 10,
                    height: 10,
                    borderRadius: '50%',
                    backgroundColor: 'error.main',
                  },
                }}
              />
            )}
          </Box>
        </Box>
      </Paper>

      {/* Summary */}
      <Box sx={{ mt: 2, display: 'flex', gap: 2, flexWrap: 'wrap' }}>
        {dayEntries.length === 0 ? (
          <Typography variant="body2" color="text.secondary">
            No time entries for this day
          </Typography>
        ) : (
          <>
            <Chip
              label={`${dayEntries.length} entries`}
              size="small"
              variant="outlined"
            />
            <Chip
              label={`Total: ${formatDuration(dayEntries.reduce((sum, e) => sum + (e.id === '__running__' ? now.getTime() - new Date(e.startTime).getTime() : e.duration), 0))}`}
              size="small"
              color="primary"
            />
          </>
        )}
      </Box>

      {/* Break duration popover */}
      <Popover
        open={Boolean(breakPopover)}
        anchorEl={breakPopover?.anchorEl}
        onClose={() => setBreakPopover(null)}
        anchorOrigin={{ vertical: 'center', horizontal: 'left' }}
        transformOrigin={{ vertical: 'center', horizontal: 'right' }}
      >
        <Box sx={{ p: 1.5, display: 'flex', flexDirection: 'column', gap: 0.5 }}>
          <Typography variant="caption" color="text.secondary" sx={{ mb: 0.5 }}>
            Break duration
          </Typography>
          {[15, 30, 45, 60].map((minutes) => (
            <Button
              key={minutes}
              size="small"
              variant="outlined"
              onClick={() => {
                if (breakPopover && onInsertBreakAtBoundary) {
                  onInsertBreakAtBoundary(breakPopover.boundaryTime, minutes);
                }
                setBreakPopover(null);
              }}
            >
              {minutes} min
            </Button>
          ))}
        </Box>
      </Popover>
    </Box>
  );
}
