import { useState, useMemo, useEffect } from 'react';
import {
  Box,
  Typography,
  Paper,
  IconButton,
  Tooltip,
  Chip,
  keyframes,
} from '@mui/material';
import {
  ChevronLeft as ChevronLeftIcon,
  ChevronRight as ChevronRightIcon,
  Today as TodayIcon,
} from '@mui/icons-material';
import { TimeEntry, Project } from '../types';
import { formatTime, formatDuration } from '../utils/timeUtils';

const pulseAnimation = keyframes`
  0% { opacity: 0.85; }
  50% { opacity: 0.55; }
  100% { opacity: 0.85; }
`;

interface WeekTimelineProps {
  timeEntries: TimeEntry[];
  projects: Project[];
  selectedDate: Date;
  onDateChange: (date: Date) => void;
  onEditEntry: (entry: TimeEntry) => void;
  onSelectDay: (date: Date) => void;
  activeProjectId?: string | null;
  currentSessionStart?: Date | null;
}

const HOUR_HEIGHT = 48; // smaller than day view
const TIMELINE_START_HOUR = 6;
const TIMELINE_END_HOUR = 22;
const TOTAL_HOURS = TIMELINE_END_HOUR - TIMELINE_START_HOUR;

function getMonday(date: Date): Date {
  const d = new Date(date);
  const day = d.getDay();
  const diff = d.getDate() - day + (day === 0 ? -6 : 1);
  d.setDate(diff);
  d.setHours(0, 0, 0, 0);
  return d;
}

function isSameDay(a: Date, b: Date): boolean {
  return a.getDate() === b.getDate() &&
    a.getMonth() === b.getMonth() &&
    a.getFullYear() === b.getFullYear();
}

const DAY_NAMES = ['Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa', 'So'];

export function WeekTimeline({
  timeEntries,
  projects,
  selectedDate,
  onDateChange,
  onEditEntry,
  onSelectDay,
  activeProjectId,
  currentSessionStart,
}: WeekTimelineProps) {
  const [now, setNow] = useState(new Date());

  useEffect(() => {
    if (!activeProjectId || !currentSessionStart) return;
    const interval = setInterval(() => setNow(new Date()), 15000);
    return () => clearInterval(interval);
  }, [activeProjectId, currentSessionStart]);

  const monday = useMemo(() => getMonday(selectedDate), [selectedDate]);

  const weekDays = useMemo(() => {
    return Array.from({ length: 7 }, (_, i) => {
      const d = new Date(monday);
      d.setDate(d.getDate() + i);
      return d;
    });
  }, [monday]);

  const today = useMemo(() => new Date(), []);

  // Group entries by day of week
  const entriesByDay = useMemo(() => {
    return weekDays.map(day => {
      const dayStart = new Date(day);
      dayStart.setHours(0, 0, 0, 0);
      const dayEnd = new Date(day);
      dayEnd.setHours(23, 59, 59, 999);

      const completed = timeEntries
        .filter(entry => {
          if (!entry.endTime) return false;
          const entryStart = new Date(entry.startTime);
          return entryStart >= dayStart && entryStart <= dayEnd;
        })
        .sort((a, b) => new Date(a.startTime).getTime() - new Date(b.startTime).getTime());

      // Add running entry if it starts on this day
      if (activeProjectId && currentSessionStart) {
        const sessionStart = new Date(currentSessionStart);
        if (sessionStart >= dayStart && sessionStart <= dayEnd) {
          const runningEntry: TimeEntry = {
            id: '__running__',
            projectId: activeProjectId,
            startTime: currentSessionStart,
            endTime: undefined,
            duration: now.getTime() - currentSessionStart.getTime(),
          };
          const insertIndex = completed.findIndex(
            e => new Date(e.startTime).getTime() > sessionStart.getTime()
          );
          if (insertIndex === -1) {
            completed.push(runningEntry);
          } else {
            completed.splice(insertIndex, 0, runningEntry);
          }
        }
      }

      return completed;
    });
  }, [weekDays, timeEntries, activeProjectId, currentSessionStart, now]);

  // Daily totals
  const dailyTotals = useMemo(() => {
    return entriesByDay.map(entries =>
      entries.reduce((sum, e) => {
        if (e.id === '__running__') return sum + (now.getTime() - new Date(e.startTime).getTime());
        return sum + e.duration;
      }, 0)
    );
  }, [entriesByDay, now]);

  const getProject = (projectId: string) => projects.find(p => p.id === projectId);

  const timeToPosition = (date: Date): number => {
    const hours = date.getHours() + date.getMinutes() / 60;
    const adjustedHours = Math.max(0, Math.min(hours - TIMELINE_START_HOUR, TOTAL_HOURS));
    return adjustedHours * HOUR_HEIGHT;
  };

  const getEntryHeight = (entry: TimeEntry): number => {
    const start = new Date(entry.startTime);
    const end = entry.endTime ? new Date(entry.endTime) : now;
    const durationHours = (end.getTime() - start.getTime()) / (1000 * 60 * 60);
    return Math.max(16, durationHours * HOUR_HEIGHT);
  };

  const handlePrevWeek = () => {
    const d = new Date(selectedDate);
    d.setDate(d.getDate() - 7);
    onDateChange(d);
  };

  const handleNextWeek = () => {
    const d = new Date(selectedDate);
    d.setDate(d.getDate() + 7);
    onDateChange(d);
  };

  const handleToday = () => {
    onDateChange(new Date());
  };

  const isCurrentWeek = useMemo(() => {
    const todayMonday = getMonday(new Date());
    return monday.getTime() === todayMonday.getTime();
  }, [monday]);

  const hourMarkers: number[] = [];
  for (let hour = TIMELINE_START_HOUR; hour <= TIMELINE_END_HOUR; hour++) {
    hourMarkers.push(hour);
  }

  // Format week range for header
  const weekLabel = useMemo(() => {
    const sun = new Date(monday);
    sun.setDate(sun.getDate() + 6);
    const fmt = (d: Date) => `${d.getDate()}.${d.getMonth() + 1}.`;
    return `${fmt(monday)} - ${fmt(sun)} ${sun.getFullYear()}`;
  }, [monday]);

  return (
    <Box sx={{ p: 2 }} role="region" aria-label="Week timeline">
      {/* Week Navigation */}
      <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center', mb: 2, gap: 1 }}>
        <IconButton onClick={handlePrevWeek} aria-label="Previous week">
          <ChevronLeftIcon />
        </IconButton>
        <Typography variant="h6" sx={{ minWidth: 220, textAlign: 'center' }}>
          KW {getISOWeek(monday)} &middot; {weekLabel}
          {isCurrentWeek && (
            <Chip label="This week" size="small" color="primary" sx={{ ml: 1 }} />
          )}
        </Typography>
        <IconButton onClick={handleNextWeek} aria-label="Next week">
          <ChevronRightIcon />
        </IconButton>
        {!isCurrentWeek && (
          <Tooltip title="Go to this week">
            <IconButton onClick={handleToday} aria-label="Go to this week">
              <TodayIcon />
            </IconButton>
          </Tooltip>
        )}
      </Box>

      {/* Week Timeline */}
      <Paper sx={{ position: 'relative', overflow: 'auto' }}>
        <Box sx={{ display: 'flex', minWidth: 700 }}>
          {/* Hour labels column */}
          <Box sx={{ width: 48, flexShrink: 0, borderRight: '1px solid', borderColor: 'divider', position: 'relative' }}>
            {/* Spacer for day headers */}
            <Box sx={{ height: 52, borderBottom: '1px solid', borderColor: 'divider' }} />
            <Box sx={{ position: 'relative', height: TOTAL_HOURS * HOUR_HEIGHT + 20 }}>
              {hourMarkers.map((hour) => (
                <Box
                  key={hour}
                  sx={{
                    position: 'absolute',
                    top: (hour - TIMELINE_START_HOUR) * HOUR_HEIGHT + 10,
                    left: 0,
                    width: 44,
                    textAlign: 'right',
                    pr: 0.5,
                  }}
                >
                  <Typography variant="caption" color="text.secondary" sx={{ fontSize: '0.65rem' }}>
                    {hour.toString().padStart(2, '0')}:00
                  </Typography>
                </Box>
              ))}
            </Box>
          </Box>

          {/* Day columns */}
          {weekDays.map((day, dayIndex) => {
            const isDayToday = isSameDay(day, today);
            const entries = entriesByDay[dayIndex];
            const total = dailyTotals[dayIndex];
            const isWeekend = dayIndex >= 5;

            return (
              <Box
                key={dayIndex}
                sx={{
                  flex: 1,
                  minWidth: 80,
                  borderRight: dayIndex < 6 ? '1px solid' : 'none',
                  borderColor: 'divider',
                  position: 'relative',
                }}
              >
                {/* Day header */}
                <Box
                  onClick={() => onSelectDay(day)}
                  sx={{
                    height: 52,
                    borderBottom: '1px solid',
                    borderColor: 'divider',
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                    justifyContent: 'center',
                    cursor: 'pointer',
                    backgroundColor: isDayToday ? 'primary.main' : isWeekend ? 'action.hover' : 'transparent',
                    color: isDayToday ? 'primary.contrastText' : 'text.primary',
                    '&:hover': {
                      backgroundColor: isDayToday ? 'primary.dark' : 'action.selected',
                    },
                  }}
                >
                  <Typography variant="caption" sx={{ fontWeight: 'bold', fontSize: '0.7rem' }}>
                    {DAY_NAMES[dayIndex]} {day.getDate()}.{day.getMonth() + 1}.
                  </Typography>
                  {total > 0 && (
                    <Typography
                      variant="caption"
                      sx={{
                        fontSize: '0.6rem',
                        color: isDayToday ? 'primary.contrastText' : 'text.secondary',
                        opacity: isDayToday ? 0.85 : 1,
                      }}
                    >
                      {formatDuration(total)}
                    </Typography>
                  )}
                </Box>

                {/* Day content */}
                <Box sx={{ position: 'relative', height: TOTAL_HOURS * HOUR_HEIGHT + 20, pt: '10px' }}>
                  {/* Hour grid lines */}
                  {hourMarkers.map((hour) => (
                    <Box
                      key={hour}
                      sx={{
                        position: 'absolute',
                        top: (hour - TIMELINE_START_HOUR) * HOUR_HEIGHT + 10,
                        left: 0,
                        right: 0,
                        borderTop: '1px solid',
                        borderColor: 'divider',
                        opacity: 0.3,
                      }}
                    />
                  ))}

                  {/* Time entries */}
                  {entries.map((entry) => {
                    const project = getProject(entry.projectId);
                    const top = timeToPosition(new Date(entry.startTime)) + 10;
                    const height = getEntryHeight(entry);
                    const isRunning = entry.id === '__running__';
                    const entryEnd = entry.endTime ? new Date(entry.endTime) : now;

                    return (
                      <Tooltip
                        key={entry.id}
                        title={
                          <Box>
                            <Typography variant="body2">
                              {project?.name || entry.projectId}
                              {isRunning ? ' (Running)' : ''}
                            </Typography>
                            <Typography variant="caption">
                              {formatTime(new Date(entry.startTime))} - {isRunning ? 'now' : formatTime(new Date(entry.endTime!))}
                            </Typography>
                            <br />
                            <Typography variant="caption">
                              Duration: {formatDuration(isRunning ? now.getTime() - new Date(entry.startTime).getTime() : entry.duration)}
                            </Typography>
                          </Box>
                        }
                        placement="top"
                      >
                        <Box
                          tabIndex={0}
                          role="button"
                          aria-label={`${project?.name || entry.projectId}: ${formatTime(new Date(entry.startTime))} - ${isRunning ? 'now' : formatTime(entryEnd)}`}
                          onClick={() => !isRunning && onEditEntry(entry)}
                          onKeyDown={(e: React.KeyboardEvent) => {
                            if (!isRunning && (e.key === 'Enter' || e.key === ' ')) {
                              e.preventDefault();
                              onEditEntry(entry);
                            }
                          }}
                          sx={{
                            position: 'absolute',
                            top,
                            left: 2,
                            right: 2,
                            height,
                            backgroundColor: project?.color || '#808080',
                            opacity: 0.85,
                            borderRadius: 0.5,
                            borderBottom: isRunning ? '2px dashed rgba(255,255,255,0.6)' : 'none',
                            cursor: isRunning ? 'default' : 'pointer',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            overflow: 'hidden',
                            ...(isRunning ? {
                              animation: `${pulseAnimation} 3s ease-in-out infinite`,
                              backgroundImage: 'repeating-linear-gradient(45deg, transparent, transparent 8px, rgba(255,255,255,0.1) 8px, rgba(255,255,255,0.1) 16px)',
                            } : {}),
                            '&:hover': {
                              opacity: 1,
                              boxShadow: 2,
                            },
                          }}
                        >
                          <Typography
                            variant="caption"
                            sx={{
                              color: 'white',
                              fontWeight: 'bold',
                              textShadow: '1px 1px 2px rgba(0,0,0,0.5)',
                              fontSize: '0.6rem',
                              whiteSpace: 'nowrap',
                              overflow: 'hidden',
                              textOverflow: 'ellipsis',
                              px: 0.25,
                            }}
                          >
                            {project?.icon} {height > 24 ? project?.name : ''}
                          </Typography>
                        </Box>
                      </Tooltip>
                    );
                  })}

                  {/* Current time indicator */}
                  {isDayToday && (
                    <Box
                      sx={{
                        position: 'absolute',
                        top: timeToPosition(new Date()) + 10,
                        left: 0,
                        right: 0,
                        height: 2,
                        backgroundColor: 'error.main',
                        zIndex: 1,
                        '&::before': {
                          content: '""',
                          position: 'absolute',
                          left: -3,
                          top: -3,
                          width: 8,
                          height: 8,
                          borderRadius: '50%',
                          backgroundColor: 'error.main',
                        },
                      }}
                    />
                  )}
                </Box>
              </Box>
            );
          })}
        </Box>
      </Paper>

      {/* Week summary */}
      <Box sx={{ mt: 2, display: 'flex', gap: 2, flexWrap: 'wrap' }}>
        <Chip
          label={`${entriesByDay.flat().length} entries`}
          size="small"
          variant="outlined"
        />
        <Chip
          label={`Week total: ${formatDuration(dailyTotals.reduce((a, b) => a + b, 0))}`}
          size="small"
          color="primary"
        />
        <Typography variant="caption" color="text.secondary" sx={{ alignSelf: 'center' }}>
          Click a day header for detailed view
        </Typography>
      </Box>
    </Box>
  );
}

function getISOWeek(date: Date): number {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  d.setDate(d.getDate() + 3 - ((d.getDay() + 6) % 7));
  const yearStart = new Date(d.getFullYear(), 0, 4);
  return 1 + Math.round(((d.getTime() - yearStart.getTime()) / 86400000 - 3 + ((yearStart.getDay() + 6) % 7)) / 7);
}
